{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "LCB01-0371, a close analogue with a basic N-methylpiperazine and heteroaromatic core, had 99.75% absolute oral bioavailability in humans after 800 mg PO versus IV, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Brigatinib, containing a piperidine and aminopyrimidine/heteroaromatic system, had approximately 46% absolute oral bioavailability in healthy volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Rufloxacin, a fluoroquinolone with a basic amine, had at least 50% oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "S-RCP, a basic amine-containing benzamide, had 65% absolute oral bioavailability from solution in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Tolvaptan had mean absolute oral bioavailability of 56% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Prasugrel had oral bioavailability of about 79% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Sildenafil had absolute oral bioavailability of 41% (90% CI 35.6-47.3) in humans, above threshold despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Amsacrine had 32% oral bioavailability in patients, still above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental absolute oral bioavailability values for close analogues are above the 20% threshold (32-99.75%), with high transfer scores; therefore predict high bioavailability.",
  "evidence_gaps": [
